package com.zomiggy.controller; import com.zomiggy.dto.ApiDtos.*; import com.zomiggy.service.*; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/orders") public class OrderController {private final OrderService service; private final DeliveryService delivery; public OrderController(OrderService s,DeliveryService d){service=s;delivery=d;} @PostMapping public Map<String,Object> create(Authentication a,@Valid @RequestBody OrderRequest r){return Map.of("order",service.create(a.getName(),r));} @GetMapping public Map<String,Object> history(Authentication a){return Map.of("orders",service.history(a.getName()));} @GetMapping("/{id}/tracking") public com.zomiggy.dto.DeliveryDtos.TrackingResponse tracking(Authentication a,@PathVariable String id){return delivery.tracking(service.owned(a.getName(),id));}}